CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
BEGIN;
SELECT no_plan();
INSERT INTO auth.users(id,aud,role,email,encrypted_password,email_confirmed_at) VALUES
 ('00000000-0000-4000-8000-000000001701','authenticated','authenticated','demo-admin@example.invalid','',now()),
 ('00000000-0000-4000-8000-000000001702','authenticated','authenticated','demo-owner@example.invalid','',now()),
 ('00000000-0000-4000-8000-000000001703','authenticated','authenticated','demo-other@example.invalid','',now());
UPDATE public.perfiles SET rol='admin' WHERE id='00000000-0000-4000-8000-000000001701';
INSERT INTO public.convocatorias(id,nombre) VALUES('00000000-0000-4000-8000-000000001710','Demostración SQL');
INSERT INTO public.temas(id,nombre) VALUES('00000000-0000-4000-8000-000000001711','Tema demostración');
INSERT INTO public.convocatoria_tema(convocatoria_id,tema_id,numero,orden) VALUES('00000000-0000-4000-8000-000000001710','00000000-0000-4000-8000-000000001711',1,1);
CREATE TEMP TABLE demo_fixture_questions AS SELECT gen_random_uuid() id,n FROM generate_series(1,5) n;
INSERT INTO public.preguntas(id,enunciado,explicacion,estado) SELECT id,'Pregunta '||n,'Explicación revisada '||n,'publicada' FROM demo_fixture_questions;
INSERT INTO public.pregunta_tema(pregunta_id,tema_id) SELECT id,'00000000-0000-4000-8000-000000001711' FROM demo_fixture_questions;
INSERT INTO public.respuestas(pregunta_id,orden,texto,es_correcta) SELECT q.id,option_number,'Opción '||option_number,option_number=1 FROM demo_fixture_questions q CROSS JOIN generate_series(1,4) option_number;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001701',true);
CREATE TEMP TABLE demo_fixture_snapshot AS SELECT private.demo_snapshot('00000000-0000-4000-8000-000000001710',(SELECT array_agg(id ORDER BY n) FROM demo_fixture_questions)) content;
SELECT public.demo_admin('publish','00000000-0000-4000-8000-000000001710',(SELECT array_agg(id ORDER BY n) FROM demo_fixture_questions),null,(SELECT content FROM demo_fixture_snapshot));
SELECT ok(NOT has_function_privilege('anon','public.demo_start(text,text)','EXECUTE'),'anonymous callers cannot bypass trusted ingress');
SELECT ok(NOT has_function_privilege('authenticated','public.demo_answer(text,text,integer,uuid)','EXECUTE'),'users cannot bypass rate limit provenance');
SELECT ok(NOT has_table_privilege('anon','private.demo_attempts','SELECT'),'attempts cannot be listed anonymously');
SELECT ok(NOT has_table_privilege('authenticated','private.demo_versions','SELECT'),'snapshots cannot be downloaded directly');
SELECT ok(NOT (public.demo_available()->'question' ? 'correctOptionId'),'preview never reveals correct option');
SELECT ok(NOT (public.demo_available()->'question' ? 'explanation'),'preview never reveals explanation');
SELECT set_config('request.jwt.claim.sub','',true);
CREATE TEMP TABLE demo_fixture_start AS SELECT public.demo_start(encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex'),repeat('b',64)) payload;
SELECT is(public.demo_start(encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex'),repeat('b',64)),(SELECT payload FROM demo_fixture_start),'retrying start creates one attempt');
SELECT is((SELECT count(*)::integer FROM private.demo_attempts WHERE credential_hash=encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex')),1,'start is idempotent');
SELECT ok(NOT ((SELECT payload FROM demo_fixture_start)->'question' ? 'correctOptionId'),'start has no pending solution');
SELECT throws_ok($$SELECT public.demo_restore(repeat('f',64))$$,'22023',NULL,'unknown token rejected');
SELECT throws_ok($$SELECT public.demo_claim(repeat('a',64))$$,'42501',NULL,'claim requires authentication');
CREATE TEMP TABLE demo_fixture_answer AS SELECT public.demo_answer(encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex'),repeat('b',64),0,((SELECT content FROM demo_fixture_snapshot)->0->>'correctOptionId')::uuid) payload;
SELECT is(public.demo_answer(encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex'),repeat('b',64),0,((SELECT content FROM demo_fixture_snapshot)->0->>'correctOptionId')::uuid),(SELECT payload FROM demo_fixture_answer),'identical answer retry returns same correction');
SELECT throws_ok($$SELECT public.demo_answer(encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex'),repeat('b',64),0,((SELECT content FROM demo_fixture_snapshot)->0->'options'->1->>'id')::uuid)$$,'22023',NULL,'confirmed choice cannot change');
SELECT is((SELECT payload FROM demo_fixture_answer)->>'score','1','server derives score');
SELECT ok(NOT ((SELECT payload FROM demo_fixture_answer)->'question' ? 'correctOptionId'),'next solution remains private');
SELECT public.demo_answer(encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex'),repeat('b',64),position,((SELECT content FROM demo_fixture_snapshot)->position->>'correctOptionId')::uuid) FROM generate_series(1,4) position ORDER BY position;
SELECT is(public.demo_restore(repeat('a',64))->>'state','completed','fifth correction completes the attempt');
SELECT is(public.demo_restore(repeat('a',64))->>'score','5','all answers are scored on server');
SELECT is(jsonb_array_length(public.demo_restore(repeat('a',64))->'results'),5,'all corrections available without account');
SELECT public.demo_start(encode(sha256(convert_to(repeat('c',64),'UTF8')),'hex'),repeat('b',64));
SELECT public.demo_start(repeat(md5(n::text),2),repeat('e',64)) FROM generate_series(1,10) n;
SELECT throws_ok($$SELECT public.demo_start(encode(sha256(convert_to(repeat('d',64),'UTF8')),'hex'),repeat('e',64))$$,'P0001',NULL,'eleventh start from the same origin is rejected');
UPDATE private.demo_settings SET answers_per_hour=5;
SELECT throws_ok($$SELECT public.demo_answer(encode(sha256(convert_to(repeat('c',64),'UTF8')),'hex'),repeat('b',64),0,((SELECT content FROM demo_fixture_snapshot)->0->>'correctOptionId')::uuid)$$,'P0001',NULL,'response limit is shared across attempts');
SELECT is(public.demo_restore(repeat('c',64))->>'answered','0','rate rejection preserves unanswered state');
UPDATE private.demo_settings SET answers_per_hour=100;
UPDATE public.preguntas SET explicacion='Edited after publication' WHERE id=(SELECT id FROM demo_fixture_questions WHERE n=1);
SELECT is(public.demo_restore(repeat('a',64))->'results'->0->>'explanation','Explicación revisada 1','bank edits do not silently change old results');
UPDATE public.preguntas SET estado='desactivada' WHERE id=(SELECT id FROM demo_fixture_questions WHERE n=1);
SELECT is(public.demo_available(),NULL::jsonb,'unavailable question stops new starts');
SELECT throws_ok($$SELECT public.demo_start(encode(sha256(convert_to(repeat('d',64),'UTF8')),'hex'),repeat('b',64))$$,'22023',NULL,'invalid set refuses new attempt');
SELECT lives_ok($$SELECT public.demo_restore(repeat('c',64))$$,'existing attempt retains its version');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001702',true);
SELECT is(public.demo_claim(repeat('a',64))->>'state','claimed','authenticated user can save completed demonstration');
SELECT is(public.demo_claim(repeat('a',64))->>'state','claimed','duplicate callback is idempotent');
SELECT is(jsonb_array_length(public.demo_my_results()),1,'saved demonstration lives outside ordinary history');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001703',true);
SELECT throws_ok($$SELECT public.demo_claim(repeat('a',64))$$,'22023',NULL,'another account cannot take ownership');
SELECT throws_ok($$SELECT public.demo_restore(repeat('a',64))$$,'22023',NULL,'public credential is revoked after ownership');
SELECT throws_ok($$SELECT public.demo_admin('list')$$,'42501',NULL,'ordinary account cannot publish or inspect versions');
SELECT set_config('request.jwt.claim.sub','',true);
UPDATE private.demo_attempts SET expires_at=clock_timestamp()-interval '1 minute';
SELECT throws_ok($$SELECT public.demo_restore(repeat('c',64))$$,'22023',NULL,'expired anonymous attempt cannot be recovered');
SELECT private.demo_cleanup();
SELECT is((SELECT count(*)::integer FROM private.demo_attempts WHERE credential_hash=encode(sha256(convert_to(repeat('c',64),'UTF8')),'hex')),0,'expired anonymous records are removed');
SELECT is((SELECT count(*)::integer FROM private.demo_attempts WHERE credential_hash=encode(sha256(convert_to(repeat('a',64),'UTF8')),'hex')),1,'saved result survives cleanup');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001702',true);
SELECT lives_ok($$SELECT public.demo_restore(repeat('a',64))$$,'owner retains access to saved result after original expiry');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001701',true);
SELECT public.demo_admin('invalidate',null,null,(SELECT id FROM private.demo_versions ORDER BY version DESC LIMIT 1));
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001702',true);
SELECT throws_ok($$SELECT public.demo_restore(repeat('a',64))$$,'22023',NULL,'invalidated version reports a restart notice');
SELECT * FROM finish();
ROLLBACK;
